            self._auto_bad_weight * delta_bad
            - self._auto_sorted_gain_weight * gain_sorted
            - self._auto_destination_bonus * destination_fit
            + self._auto_height_pressure_weight * height_pressure
        )

    def update(self, partial, state, memory, action):
        return memory


